const products=[
{id:1,name:"Tour Distance Golf Balls",category:"Balls",price:2499,tag:"PLAYER FAVOURITE",desc:"A sample two-piece ball concept for the golfer who values a consistent feel.",shape:"ball",options:["Dozen","Half dozen"]},
{id:2,name:"Everyday Performance Polo",category:"Apparel",price:3299,tag:"NEW SEASON",desc:"A sample lightweight polo concept designed for comfort on and off the course.",shape:"shirt",options:["S","M","L","XL"]},
{id:3,name:"Fairway Carry Bag",category:"Bags",price:8499,tag:"FIELD ESSENTIAL",desc:"A sample carry bag concept with considered storage and a clean silhouette.",shape:"bag",options:["Standard"]},
{id:4,name:"Soft Feel Practice Balls",category:"Balls",price:1299,tag:"PRACTICE",desc:"A sample practice ball listing for range sessions and training.",shape:"ball",options:["Pack of 6","Pack of 12"]},
{id:5,name:"Course Walk Golf Shoes",category:"Footwear",price:6999,tag:"COMFORT",desc:"A sample footwear listing with size selection required before purchase.",shape:"shoe",options:["UK 7","UK 8","UK 9","UK 10"]},
{id:6,name:"Modern Course Shirt",category:"Apparel",price:2899,tag:"ESSENTIAL",desc:"A sample apparel listing; fabric and care specifications require verified product data.",shape:"shirt",options:["S","M","L","XL"]}
];
let selectedProduct=products[0],quantity=1,cart=[];
const money=n=>"₹"+n.toLocaleString("en-IN");
const el=id=>document.getElementById(id);
function showView(name){document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));const target=el("view-"+name)||el("view-home");target.classList.add("active");document.querySelectorAll("[data-view]").forEach(a=>a.setAttribute("aria-current",a.dataset.view===name?"page":"false"));el("mobile-nav").hidden=true;el("menu-toggle").setAttribute("aria-expanded","false");window.scrollTo({top:0,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});if(name==="cart")renderCart();if(name==="checkout")renderCheckout()}
document.addEventListener("click",e=>{const nav=e.target.closest("[data-view]");if(nav){e.preventDefault();showView(nav.dataset.view)}});
function productCard(p){return `<article class="product-card"><div class="product-image" role="button" tabindex="0" data-product="${p.id}" aria-label="View ${p.name}"><span class="product-tag">${p.tag}</span><div class="product-shape ${p.shape}">${p.shape==="ball"?"F":p.shape==="bag"?"FW":p.shape==="shoe"?"":" "}</div></div><div class="product-info"><small>${p.category} / SAMPLE ITEM</small><h3>${p.name}</h3><div class="product-meta"><strong>${money(p.price)}</strong><button class="quick-view" data-product="${p.id}">View details ↗</button></div></div></article>`}
function renderProducts(){const term=(el("search").value||"").trim().toLowerCase(),cat=el("category-filter")?.value||"All",sort=el("sort-filter")?.value||"featured";let list=products.filter(p=>(cat==="All"||p.category===cat)&&(!term||(p.name+" "+p.category).toLowerCase().includes(term)));if(sort==="low")list.sort((a,b)=>a.price-b.price);if(sort==="high")list.sort((a,b)=>b.price-a.price);el("shop-products").innerHTML=list.map(productCard).join("");el("home-products").innerHTML=products.slice(0,3).map(productCard).join("");el("result-count").textContent=list.length+" products";el("empty-state").hidden=list.length!==0}
function openProduct(id){selectedProduct=products.find(p=>p.id===Number(id))||products[0];quantity=1;el("product-category").textContent=selectedProduct.category+" / SAMPLE ITEM";el("product-title").textContent=selectedProduct.name;el("product-price").textContent=money(selectedProduct.price);el("product-description").textContent=selectedProduct.desc;el("quantity").textContent=quantity;el("product-options").innerHTML=selectedProduct.options.map((o,i)=>`<button type="button" class="option ${i===0?"selected":""}" aria-pressed="${i===0}" data-option>${o}</button>`).join("");showView("product")}
function addToCart(){const item=cart.find(x=>x.id===selectedProduct.id);const option=el("product-options").querySelector(".selected")?.textContent||selectedProduct.options[0];if(item&&item.option===option)item.qty+=quantity;else cart.push({...selectedProduct,qty:quantity,option});updateCount();toast("Added to sample bag — no order was created.")}
function updateCount(){el("cart-count").textContent=cart.reduce((s,x)=>s+x.qty,0)}
function renderCart(){const root=el("cart-items");if(!cart.length){root.innerHTML='<div class="empty-cart"><span>✳</span><h2>Your bag is taking a walk.</h2><p>Add something from the collection to see it here.</p><button class="btn btn-dark" data-view="shop">Explore the shop</button></div>'}else{root.innerHTML=cart.map(x=>`<div class="cart-row"><div class="cart-thumb">${x.shape.toUpperCase()}</div><div><h3>${x.name}</h3><p>${x.option} · Qty ${x.qty}</p><strong>${money(x.price*x.qty)}</strong></div><button class="remove-item" data-remove="${x.id}">Remove</button></div>`).join("")}const total=cart.reduce((s,x)=>s+x.price*x.qty,0);el("subtotal").textContent=money(total);el("total").textContent=money(total)}
function renderCheckout(){const total=cart.reduce((s,x)=>s+x.price*x.qty,0);el("checkout-lines").innerHTML=cart.length?cart.map(x=>`<div class="summary-line"><span>${x.name} × ${x.qty}</span><strong>${money(x.price*x.qty)}</strong></div>`).join(""):'<p class="micro-note">Your bag is empty.</p>';el("checkout-total").textContent=money(total)}
function toast(message){const t=el("toast");t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,2600)}
document.addEventListener("click",e=>{const p=e.target.closest("[data-product]");if(p)openProduct(p.dataset.product);const f=e.target.closest("[data-filter]");if(f){el("category-filter").value=f.dataset.filter;document.querySelectorAll(".filter-link").forEach(x=>x.classList.toggle("active",x===f));showView("shop");renderProducts()}const r=e.target.closest("[data-remove]");if(r){cart=cart.filter(x=>x.id!==Number(r.dataset.remove));updateCount();renderCart()}if(e.target.matches("[data-option]")){el("product-options").querySelectorAll("[data-option]").forEach(x=>{x.classList.toggle("selected",x===e.target);x.setAttribute("aria-pressed",String(x===e.target))})}});
document.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches("[data-product]")){e.preventDefault();openProduct(e.target.dataset.product)}});
el("search").addEventListener("input",()=>{showView("shop");renderProducts()});el("category-filter").addEventListener("change",renderProducts);el("sort-filter").addEventListener("change",renderProducts);el("clear-filters").addEventListener("click",()=>{el("search").value="";el("category-filter").value="All";renderProducts()});
el("qty-minus").addEventListener("click",()=>{quantity=Math.max(1,quantity-1);el("quantity").textContent=quantity});el("qty-plus").addEventListener("click",()=>{quantity=Math.min(10,quantity+1);el("quantity").textContent=quantity});el("add-to-cart").addEventListener("click",addToCart);el("checkout-button").addEventListener("click",()=>{if(!cart.length){toast("Your bag is empty.");return}showView("checkout")});el("checkout-form").addEventListener("submit",e=>{e.preventDefault();toast("Checkout is disabled in this prototype.")});
el("menu-toggle").addEventListener("click",()=>{const n=el("mobile-nav");n.hidden=!n.hidden;el("menu-toggle").setAttribute("aria-expanded",String(!n.hidden))});
document.querySelectorAll(".category-card").forEach(c=>c.addEventListener("click",()=>{showView("shop");el("category-filter").value=c.dataset.filter;renderProducts()}));
renderProducts();
